from pathlib import Path
import json,datetime
P=Path(__file__).resolve().parents[1]
r=json.loads((P/'results/results.json').read_text());b=json.loads((P/'benchmark/benchmark.json').read_text());s=r['summary'];lookup={c['id']:c for c in b['cases']};docs={d['id']:d for d in b['documents']}
pct=lambda v:f'{v*100:.1f}'.replace('.',',')+' %'
metric=lambda x:f"{x['correct']}/{x['total']} ({pct(x['accuracy'])})"
lines=['# Clef: Verständnis synthetischer Versicherungsunterlagen','',f"- Entscheidung richtig: **{metric(s['decision'])}**",f"- Belegmenge richtig: **{metric(s['evidence'])}**",f"- Vollständig richtiger Fall: **{metric(s['exact_case'])}**",'', '60 deutschsprachige Fälle, sechs Bereiche und zwölf synthetische Dokumentpakete. Je fünf Fälle teilen dieselben Klauseln. Das ist ein kleiner kontrollierter Funktionstest, kein unabhängiger oder repräsentativer Produktionstest. Alle Bedingungen und Fälle sind erfunden; keine reale Produkt- oder Rechtsberatung.','', '## Nach Verständnisbereich','', '| Bereich | Entscheidung | Belegmenge | Vollständiger Fall |','|---|---:|---:|---:|']
for area,sc in r['by_area'].items():lines.append(f"| {area} | {metric(sc['decision'])} | {metric(sc['evidence'])} | {metric(sc['exact_case'])} |")
lines+=['','## Fehlerbild','',f"Nur die Entscheidung richtig, Belegmenge falsch: {sum(x['correct']['decision'] and not x['correct']['evidence'] for x in r['cases'])} Fälle. Nur die Belegmenge richtig, Entscheidung falsch: {sum(x['correct']['evidence'] and not x['correct']['decision'] for x in r['cases'])} Fälle.",'','| Referenzentscheidung | Richtige Entscheidung | Vollständiger Fall |','|---|---:|---:|']
for label,sc in r['by_decision_label'].items():lines.append(f"| {label} | {metric(sc['decision'])} | {metric(sc['exact_case'])} |")
for field,name in [('decision','Entscheidung'),('evidence','Belegmenge')]:
 errors=s['high_confidence_errors'][field];lines+=['',f"{name}: {len(errors)} falsche Auswahlen mit mindestens 90 % maximalem Softmax-Wert"+((': '+', '.join(x['id'] for x in errors)+'.') if errors else '.')]
lines+=['','Die vollständige Fehlerliste enthält jeden abweichenden Fall samt exaktem Modelloutput, Referenz und Klauseltext in [ERRORS.md](ERRORS.md). Eine passende Belegmenge allein beweist nicht, dass Clef sie kausal für die Entscheidung verwendet hat. Hohe Softmax-Werte sind keine validierte Zuverlässigkeitsgarantie.','','## Kontrolle der Rechenabgrenzung','',f"Keine Summen, Betragsklassen, Selbstbeteiligungen oder Fristberechnungen. Die drei explizit markierten Fälle zur Anwendung eines Nachtragsdatums erreichen {metric(r['date_version_subset']['exact_case'])} vollständig richtige Fälle. Ohne diese drei Fälle: {metric(r['without_date_version_subset']['decision'])} Entscheidungen, {metric(r['without_date_version_subset']['evidence'])} Belegmengen und {metric(r['without_date_version_subset']['exact_case'])} vollständige Fälle.",'','## Vergleichsmaßstab und Lauf','',f"Die häufigste Referenzentscheidung ist `nein`; ständiges Wählen der häufigsten Klasse erzielt {pct(s['decision_majority_baseline'])}. Klassen-Balanced-Accuracy des Modells: {pct(s['decision_balanced_accuracy'])}. Eine gleichverteilte zufällige Belegauswahl erzielt im Erwartungswert 20 %. Diese Baselines ersetzen keine größere externe Validierung.",'',f"Ein primärer Lauf mit {s['cases']} Fällen und {s['field_accuracy']['total']} nativen Choice-Feldern. Alle {s['cases']} vollständigen Inputs passten ungekürzt in den unveränderten 2.048-Token-Deckel: {s['tokens']['min']}–{s['tokens']['max']} Tokens, Median {s['tokens']['median']}. Median der reinen Inferenzzeit {s['latency_seconds']['median']:.2f} s/Fall, P95 (Nearest Rank) {s['latency_seconds']['p95_nearest_rank']:.2f} s. Laden und separates Warm-up sind nicht darin enthalten.",'','Modell: `Cloudflare/clef-flash`, Revision `17f0b0ad64efb65d273590632833508766b2aae6`. CPU NF4, BF16-Rechnung und originaler BF16-Joint-Head sowie Ausgabe-Embeddings, Batch 1, sechs Threads. Dieselbe Laufzeit und derselbe unveränderte Runner wie im vorausgehenden Textpilot. Kein paralleler Modellprozess und kein Upgrade. Diese Konfiguration ist keine Hersteller-GPU- oder ROCm-Leistungsmessung.','','## Nachvollziehbarkeit','', 'Alle Labels und Belegoptionen wurden vor Inferenz durch einen separaten KI-Reviewer überprüft und korrigiert, dann per SHA-256 eingefroren. Keine externe menschliche Fachprüfung. Der Inferenzprozess las nur die label-freien Requests. Die Referenzbegründungen stammen aus dem Testdatensatz, nicht aus Clef. Primärer Lauf ohne Nachoptimierung von Labels oder Prompts anhand der Ergebnisse.','', 'Vollständige Methodik: [METHODOLOGY.md](METHODOLOGY.md). Daten: `benchmark/`; tatsächliche Modelloutputs und ungerundete Wahrscheinlichkeiten: `results/`; Vorab-Freeze, Audit und nachträgliche unabhängige Score-QA: `qa/`. Reproduktion: `scripts/reproduce.sh`. Eine vollständige Neuinstallation wurde für diese Veröffentlichung nicht zusätzlich ausgeführt; der dokumentierte Lauf nutzt die bereits gepinnte Umgebung.','']
(P/'REPORT.md').write_text('\n'.join(lines))
err=['# Vollständige Fehlerliste','', 'Die Texte unter „Referenz“ sind geprüfte Testreferenzen. Clef erzeugt keine freie Begründung; angezeigt werden ausschließlich seine nativen Auswahlfelder und Wahrscheinlichkeiten. Alle Policen und Szenarien sind synthetisch.','']
for row in r['cases']:
 if row['correct']['exact_case']:continue
 c=lookup[row['id']];d=docs[c['document_id']];needed=set(c['expected']['evidence_clauses'])|set(row['actual_evidence_clauses'])
 err += [f"## {row['id']} · {c['area']}",'',f"**Sachverhalt:** {c['scenario']}",'',f"**Aussage:** {c['claim']}",'',f"**Entscheidung:** Modell `{row['actual']['decision']}` ({pct(row['probabilities']['decision'][row['actual']['decision']])}); Referenz `{c['expected']['decision']}`.",'',f"**Belegmenge:** Modell {', '.join(row['actual_evidence_clauses'])} ({pct(row['probabilities']['evidence'][row['actual']['evidence']])}); Referenz {', '.join(c['expected']['evidence_clauses'])}.",'',f"**Referenzerläuterung:** {c['rationale']}",'']
 for clause in d['clauses']:
  if clause['id'] in needed:err.append(f"- **{clause['id']}:** {clause['text']}")
 err+=['']
if all(x['correct']['exact_case'] for x in r['cases']):err.append('In diesem Lauf gab es keine abweichenden Fälle.')
(P/'ERRORS.md').write_text('\n'.join(err)+'\n')
print(json.dumps({'report':'REPORT.md','errors':'ERRORS.md','incorrect_cases':sum(not x['correct']['exact_case'] for x in r['cases'])}))
